<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionSubjectVO;

trait SnippetVersionSubjectAttributeHolder
{
    protected SnippetVersionSubjectVO|string|null $subject = null;
    protected bool $subjectAssigned = false;

    public function getSubjectOrCurrent(?SnippetVersionSubjectVO $subject): ?SnippetVersionSubjectVO
    {
        return $this->subjectAssigned ? ($this->subject === null ? null : SnippetVersionSubjectVO::from($this->subject)) : $subject;
    }
    public function subjectTryBuildInitial(ConstraintFailList $error): ?SnippetVersionSubjectVO
    {
        return  SnippetVersionSubjectVO::tryFrom($this->subjectAssigned ? $this->subject : null, $error);
    }
    public function subject(SnippetVersionSubjectVO|string|null $subject): static
    {
        $this->subject = $subject;
        $this->subjectAssigned = true;
        return $this;
    }
    public function getSubject(): ?string
    {
        return $this->subject instanceof SnippetVersionSubjectVO ? $this->subject->value() : $this->subject;
    }
    public function isSubjectAssigned(): bool
    {
        return $this->subjectAssigned;
    }
    public function writeSubjectTo(mixed $att): void
    {
        if ($this->subjectAssigned) {
            $att->subject($this->subject);
        }
    }
    public function readSubjectFrom(mixed $att): void
    {
        if ($att->isSubjectAssigned()) {
            $subject = $att->getSubject();
            $this->subject($subject);
        }
    }
    public function unsetSubject(): static
    {
        $this->subjectAssigned = false;
        return $this;
    }
    protected function withDefaultSubject(): void
    {
    }
    protected function withAssertedSubjectRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->subjectAssigned = $this->subjectAssigned) {
            $value->subject = SnippetVersionSubjectVO::tryFrom($this->subject, $errorsList);
        }
    }
}
